insert into public.destinations (id, name, slug, country, country_code, region, city, tagline, description, latitude, longitude, cover_image, cover_alt, scene, experiences, featured, sort_order, published, created_at, updated_at) values
  ('be0de758-84a1-5d60-8afb-891650bbd6a6', 'Bali', 'bali', 'Indonesia', 'ID', 'Bali Province', null, 'Clifftops, caldera lakes and courts carved into the island''s green interior.', 'Bali is COURTSCAPE''s first editorial base. Our research shortlist spans the clifftops of the Bukit Peninsula, the bay at Jimbaran, the river valleys around Ubud and the cool highlands near Bedugul. Every listing below is a research candidate: we publish what public sources say, label it clearly, and update each venue as we verify it in person.', -8.4095, 115.1889, null, null, 'cliff', array['ocean', 'jungle', 'mountain', 'luxury']::text[], true, 1, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('1e6fd52d-bd01-576e-b910-ffc607ebbcc4', 'Lombok', 'lombok', 'Indonesia', 'ID', 'West Nusa Tenggara', null, 'Bali''s quieter neighbour, where the volcano watches over the coast.', 'East of Bali across the Lombok Strait, Lombok rewards travellers who want more space and slower days. Our research begins on the Senggigi coast on the island''s west side.', -8.65, 116.32, null, null, 'volcano', array['ocean', 'hidden']::text[], true, 2, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('5af74c7d-9c43-53d2-98f1-a9d88e0ef8e8', 'Java', 'java', 'Indonesia', 'ID', null, null, 'Highland towns, volcanic ridges and the courts of Indonesia''s busiest island.', 'Java''s highland towns and cities have a long tennis culture. Venue research for Java is in progress; listings will appear here once sourced.', -7.6145, 110.7122, null, null, 'terraces', array['mountain', 'city', 'hidden']::text[], true, 3, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('add640e5-bf80-53fb-8736-764ecf299c97', 'Maldives', 'maldives', 'Maldives', 'MV', null, null, 'Floodlit courts a few steps from the lagoon.', 'A handful of Maldivian island resorts keep tennis courts among the palms. Our shortlist focuses on resorts whose own materials explicitly describe their courts.', 3.2028, 73.2207, null, null, 'lagoon', array['ocean', 'luxury']::text[], true, 4, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('27790371-0556-5829-a6b7-e16e5b7844e9', 'Switzerland', 'switzerland', 'Switzerland', 'CH', null, null, 'Summer clay beneath the peaks of the Bernese Oberland and the Engadin.', 'The grand hotels of the Swiss Alps have played summer tennis on clay for generations. We begin with Gstaad and St. Moritz.', 46.8182, 8.2275, null, null, 'alpine', array['mountain', 'luxury']::text[], true, 5, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('72d3689a-b2ba-5eb2-b54f-9e4a28ad54f1', 'Japan', 'japan', 'Japan', 'JP', null, null, 'Highland resort courts in Nagano and island tennis in Okinawa.', 'From the forested resort town of Karuizawa to the subtropical coast of Okinawa, Japan offers two very different tennis escapes.', 36.2048, 138.2529, null, null, 'zen', array['mountain', 'ocean', 'luxury']::text[], true, 6, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z')
insert into public.venues (id, destination_id, name, slug, venue_type, setting, experiences, summary, description, address, city, website, booking_url, phone, email, latitude, longitude, coordinates_approximate, access_type, accommodation_available, verification_status, verification_notes, last_verified_at, cover_image, cover_alt, scene, featured, published, created_at, updated_at) values
  ('dec66104-a87c-596a-8fdd-ff9471026058', 'be0de758-84a1-5d60-8afb-891650bbd6a6', 'Handara Golf & Resort Bali', 'handara-golf-resort-bali', 'resort', 'mountain', array['mountain', 'hidden']::text[], 'A highland resort in Bali''s caldera valley, with an outdoor tennis court framed by mountain views.', 'Handara sits in the cool uplands of northern Bali, in the caldera valley near Pancasari and the Bedugul lakes. The resort''s own tennis page describes an outdoor mountain court. Public sources indicate the court can also be hired by non-guests, and that the tennis house was being upgraded while the court remained open.', null, 'Pancasari, Bedugul', 'https://www.handaragolfresort.com/', null, null, null, -8.27, 115.16, true, 'public', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Sources disagree on the number of courts (one court on the official page; two named courts in a third-party listing).', null, null, null, 'mountain', true, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('b12e166a-0769-5459-8134-25068184fb9b', 'be0de758-84a1-5d60-8afb-891650bbd6a6', 'The Ungasan Clifftop Resort', 'the-ungasan-clifftop-resort', 'resort', 'beach', array['ocean', 'luxury']::text[], 'A clifftop resort on the Bukit Peninsula with a synthetic grass court described on its facilities page.', 'Perched on the limestone cliffs of Bali''s southern Bukit Peninsula, The Ungasan describes a professional synthetic grass court on its facilities page, with court time booked through the guest butler service and equipment provided.', null, 'Ungasan, Uluwatu', 'https://theungasan.com/', null, null, null, -8.83, 115.17, true, 'guests_only', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Facilities page refers to one court; an FAQ page refers to ''courts''. Guest-only access is inferred from the butler booking process, not explicitly stated.', null, null, null, 'cliff', true, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('e46d8510-e4ce-588d-ac85-e47905a67316', 'be0de758-84a1-5d60-8afb-891650bbd6a6', 'Kula Mani Tennis Village', 'kula-mani-tennis-village', 'club', 'countryside', array['jungle', 'hidden']::text[], 'A dedicated tennis village with hard courts and red clay courts, set among Bali''s rice fields.', 'Kula Mani presents itself as a tennis village: official pages describe hard courts — including grandstand courts overlooking rice fields — alongside two red clay courts, plus padel and pickleball. The precise location is not yet confirmed by an official page.', null, null, 'https://kulamani.com/', null, null, null, null, null, true, 'unknown', null, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Total court count is unconfirmed (official pages describe five hard courts plus two clay courts on separate pages). A Mouratoglou Tennis Center listing for Bali may refer to the same complex — not confirmed.', null, null, null, 'terraces', true, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('bf52a95b-2ecf-5903-acbd-86abacceaea3', 'be0de758-84a1-5d60-8afb-891650bbd6a6', 'Amandari', 'amandari', 'resort', 'jungle', array['jungle', 'luxury']::text[], 'Aman''s resort above Ubud, with a floodlit hard court and hitting partners on request.', 'Amandari sits in Kedewatan, just outside Ubud. Aman''s published fact sheet describes a floodlit hard court with hitting partners available, and the resort''s experience guide lists rackets on request.', 'Jl. Raya Kedewatan, Ubud (per third-party listing)', 'Kedewatan, Ubud', 'https://www.aman.com/resorts/amandari', null, null, null, -8.49, 115.25, true, 'unknown', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Court hours differ between sources. Court count is not stated explicitly.', null, null, null, 'jungle', true, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('05be17f1-0b83-5709-9f5a-f8be8098b3e5', 'be0de758-84a1-5d60-8afb-891650bbd6a6', 'Raffles Bali', 'raffles-bali', 'resort', 'beach', array['ocean', 'luxury']::text[], 'A Jimbaran hillside resort listing two clay-surface tennis and pickleball courts for in-house guests.', 'Raffles Bali''s official pages describe two clay-surface courts shared between tennis and pickleball. The resort''s activities booklet states that the courts are reserved for in-house guests, bookable in advance, with coaching available at an additional fee.', null, 'Jimbaran', 'https://www.raffles.com/bali/', null, null, null, -8.79, 115.16, true, 'guests_only', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Older materials refer to a single court; newer pages to two courts shared with pickleball.', null, null, null, 'ocean', false, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('4f7e8097-cec7-5d93-a640-a922594a5db6', 'be0de758-84a1-5d60-8afb-891650bbd6a6', 'InterContinental Bali Resort', 'intercontinental-bali-resort', 'resort', 'beach', array['ocean']::text[], 'A large resort on Jimbaran Bay whose recreation page lists a beachfront tennis court.', 'The InterContinental on Jimbaran Bay lists tennis among its recreational activities. Not to be confused with InterContinental Bali Sanur Resort.', null, 'Jimbaran Bay', 'https://bali.intercontinental.com/', null, null, null, -8.79, 115.16, true, 'unknown', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Court count and surface vary across third-party listings; no official figure found.', null, null, null, 'ocean', false, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('802182eb-4731-5b30-ae69-3b750c7e083e', '1e6fd52d-bd01-576e-b910-ffc607ebbcc4', 'Sheraton Senggigi Beach Resort', 'sheraton-senggigi-beach-resort', 'resort', 'beach', array['ocean', 'hidden']::text[], 'A beachfront resort on Lombok''s west coast whose experiences page mentions its tennis court.', 'On the Senggigi coast of West Lombok, the Sheraton''s experiences page mentions a tennis court. Some of the public material is several years old, so the court''s current status needs confirming.', null, 'Senggigi', 'https://www.marriott.com/en-us/hotels/lopsi-sheraton-senggigi-beach-resort/overview/', null, null, null, -8.49, 116.04, true, 'unknown', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Fees and current operation should be confirmed with the resort.', null, null, null, 'volcano', true, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('e588b53a-c1a5-5e35-a097-60fe72725b66', 'add640e5-bf80-53fb-8736-764ecf299c97', 'Jumeirah Olhahali Island', 'jumeirah-olhahali-island', 'resort', 'island', array['ocean', 'luxury']::text[], 'An island resort in North Malé Atoll with a floodlit beachfront court and social tennis sessions.', 'Jumeirah''s tennis page describes a floodlit court so play can continue after sunset, with complimentary rackets and balls and regular social sessions. The resort appears to have been renamed from Jumeirah Maldives Olhahali Island.', null, 'North Malé Atoll', 'https://www.jumeirah.com/en/stay/maldives/jumeirah-olhahali-island', null, null, null, 4.4, 73.5, true, 'guests_only', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Coordinates are an approximate atoll position. Guest-only access is assumed for a private-island resort, not stated.', null, null, null, 'lagoon', true, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('391f2770-cd45-5047-9754-f3bb87cbf423', 'add640e5-bf80-53fb-8736-764ecf299c97', 'Vakkaru Maldives', 'vakkaru-maldives', 'resort', 'island', array['ocean', 'luxury']::text[], 'A Baa Atoll resort with two floodlit all-weather courts for day and night play.', 'Vakkaru''s sports fields page describes all-weather floodlit tennis courts, and its 2025 fact sheet lists two. A padel court has also been added.', null, 'Baa Atoll', 'https://www.vakkarumaldives.com/', null, null, null, 5.1, 73, true, 'guests_only', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Coordinates are an approximate atoll position. Surface type is described only as ''all-weather''.', null, null, null, 'lagoon', false, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('54658c43-95cd-5412-8caa-0d4ebe8b8d31', '27790371-0556-5829-a6b7-e16e5b7844e9', 'Gstaad Palace', 'gstaad-palace', 'hotel', 'mountain', array['mountain', 'luxury']::text[], 'The grand hotel above Gstaad, with four outdoor clay courts and a long tennis history.', 'Gstaad Palace describes four clay courts beside the hotel, used mainly in summer, with nearby indoor courts available in bad weather. The hotel is closely tied to the history of Swiss tennis and hosts long-running tennis weeks with Roy Emerson.', null, 'Gstaad', 'https://www.palace.ch/', null, null, null, 46.475, 7.286, true, 'on_request', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Primarily a summer facility. A tourism listing suggests the courts can be booked, but public access is not stated outright.', null, null, null, 'alpine', true, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('f3d4213c-5558-551c-8122-e79164b390a7', '27790371-0556-5829-a6b7-e16e5b7844e9', 'Suvretta House', 'suvretta-house', 'hotel', 'mountain', array['mountain', 'luxury']::text[], 'A St. Moritz grand hotel with three clay courts in front of the house and a resident tennis pro.', 'Suvretta House''s summer pages describe three clay courts in front of the hotel, lessons with the hotel''s tennis professional and a ball machine. Spa Club members are reported to have summer court access.', null, 'St. Moritz', 'https://suvrettahouse.ch/', null, null, null, 46.498, 9.839, true, 'members', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Summer-only facility. Seasonal dates and prices not found.', null, null, null, 'alpine', false, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('f8629b64-894d-5c85-8eac-05089e8b0839', '72d3689a-b2ba-5eb2-b54f-9e4a28ad54f1', 'Karuizawa Prince Hotel West', 'karuizawa-prince-hotel-west', 'resort', 'mountain', array['mountain']::text[], 'A forest resort in Nagano''s highland town of Karuizawa with artificial turf courts.', 'Karuizawa has been a summer retreat for generations. The Prince Hotel West''s facilities pages describe artificial turf courts, some lit for night play, shared across the East and West hotels.', null, 'Karuizawa', 'https://www.princehotels.com/karuizawa-west/', null, null, null, 36.34, 138.63, true, 'unknown', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Official pages give a combined figure for the East and West hotels; the West-only count is not confirmed.', null, null, null, 'zen', true, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('5533f5ee-4cfa-5e74-8efc-d45ff62f55f1', '72d3689a-b2ba-5eb2-b54f-9e4a28ad54f1', 'Halekulani Okinawa', 'halekulani-okinawa', 'resort', 'beach', array['ocean', 'luxury']::text[], 'A coastal resort in Onna, Okinawa, offering hourly court hire with racket and shoe rental.', 'Halekulani Okinawa''s tennis page lists hourly court hire including rental rackets and shoes, with advance reservation required.', null, 'Onna Village', 'https://www.okinawa.halekulani.com/en/', null, null, null, 26.5, 127.85, true, 'unknown', true, 'public_sources', 'Compiled from public sources (search excerpts of official pages) on 6 Nov 2026. Not yet confirmed with the venue or visited by COURTSCAPE. Check details directly with the venue before travelling. Court count differs between booking sites and official pages.', null, null, null, 'ocean', false, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z')
