  ('6198ad47-d4b3-546d-b5fc-6195d05e324d', '05be17f1-0b83-5709-9f5a-f8be8098b3e5', 'Tennis & pickleball courts', 'clay', null, null, null, 2, null, null, 'Reported: in-house guests only; book at least two hours ahead; coach or partner at extra fee.', 'public_sources', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('eda044f7-6517-55d0-b361-a5ba94b98fee', '4f7e8097-cec7-5d93-a640-a922594a5db6', 'Beachfront court', null, null, null, null, null, null, null, null, 'public_sources', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('843d6a5b-ff19-5496-ac2b-fd590210cd5c', '802182eb-4731-5b30-ae69-3b750c7e083e', 'Tennis court', null, null, null, null, null, null, null, null, 'public_sources', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('086d3604-e124-5d80-8bb6-0df2055dfd22', 'e588b53a-c1a5-5e35-a097-60fe72725b66', 'Beachfront court', null, null, null, true, null, null, null, 'Reported: complimentary rackets and balls; kids'' clinics and adult social tennis on set days.', 'public_sources', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('8622dcbc-49b3-5359-8a6c-8566f823c2be', '391f2770-cd45-5047-9754-f3bb87cbf423', 'Tennis courts', null, null, null, true, 2, null, null, null, 'public_sources', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('f70c260c-c685-50e6-ab6d-430b24043561', '54658c43-95cd-5412-8caa-0d4ebe8b8d31', 'Clay courts', 'clay', 'outdoor', null, null, 4, null, null, null, 'public_sources', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('ed31ae4b-593d-5525-bdf7-9507c26a3b46', 'f3d4213c-5558-551c-8122-e79164b390a7', 'Clay courts', 'clay', null, null, null, 3, null, null, 'Reported: lessons with the hotel tennis pro; ball machine available.', 'public_sources', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('ef5ca6ba-5d9c-5c0b-9de3-878201b6629b', 'f8629b64-894d-5c85-8eac-05089e8b0839', 'Tennis courts', 'artificial_grass', 'outdoor', null, null, null, null, null, 'Reported: fee applies; rental equipment available; reception at the hot-spring building.', 'public_sources', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('88b92a34-ecc3-52a3-9468-39abd774691d', '5533f5ee-4cfa-5e74-8efc-d45ff62f55f1', 'Tennis court', null, null, null, null, null, null, null, 'Reported: reserve at least one hour ahead; rental racket and shoes included in hourly fee.', 'public_sources', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z')
insert into public.facilities (id, venue_id, category, name, description, verification_status, created_at, updated_at) values
