insert into public.venue_sources (id, venue_id, url, title, fact, accessed_at, created_at, updated_at) values
  ('9d1f7317-9f84-552e-894b-0bb3d76ca017', 'dec66104-a87c-596a-8fdd-ff9471026058', 'https://www.handaragolfresort.com/experience/tennis/', 'Tennis — Handara (official)', 'Outdoor mountain court; court hire for non-guests with a separate hotel-guest rate reported (rates not confirmed); tennis house upgrade noted.', '2026-11-06', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
