insert into public.articles (id, title, slug, excerpt, body, cover_image, cover_alt, scene, author, category, tags, related_destination_id, related_venue_id, published_at, seo_title, seo_description, featured, published, created_at, updated_at) values
  ('6494b0ed-428c-5137-b98e-416b76236a3e', 'The Tennis Escape Score: how we rate a court', 'tennis-escape-score-how-we-rate', 'Five categories, one honest number — and why we refuse to publish a score until we''ve played there ourselves.', 'A beautiful court is not the same thing as a great tennis escape. The most photographed court in a region can have a cracked surface and no shade; a modest club court can come with a coach, a café and the best sunset on the island. The **Tennis Escape Score** exists to tell those stories apart.
