insert into public.guides (id, title, slug, subtitle, description, contents, includes, page_count, format, price, currency, cover_image, scene, related_destination_id, downloadable_file, status_note, published, featured, created_at, updated_at) values
  ('aece71a6-b258-5af7-850d-5590aa93b973', 'Bali Tennis Escape Guide', 'bali-tennis-escape-guide', 'Where to play, stay and slow down on the Island of the Gods.', 'A beautifully designed digital guide to tennis travel in Bali: the island''s most interesting courts, how to book them, where to stay, and how to build a trip that balances matches with everything else Bali does so well. Built from COURTSCAPE''s on-the-ground research.', array['Bali at a glance: regions, seasons and getting around', 'The courts: clifftop, beach, jungle and highland venues', 'Booking court time as a guest and as a visitor', 'Coaching, hitting partners and equipment', 'Sample itineraries: a long weekend, a week and a family trip', 'Where to stay: resorts with tennis', 'Beyond the court: food, wellness and day trips']::text[], array['Printable PDF optimised for phone and tablet', 'Interactive map links for every venue', 'Booking checklist', 'Free updates for the first edition']::text[], null, 'PDF', 19, 'USD', null, 'cliff', 'be0de758-84a1-5d60-8afb-891650bbd6a6', 'guides/bali-tennis-escape-guide.pdf', 'Pre-launch edition. The guide''s content is being finalised after venue verification.', true, true, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('0549cbf8-b87d-56f8-b2e0-685541b61145', 'Alpine Clay Guide', 'alpine-clay-guide', 'Summer tennis in the grand hotels of the Swiss Alps.', 'Our forthcoming guide to summer clay-court tennis in Switzerland''s mountain resorts.', array['Gstaad and the Saanenland', 'St. Moritz and the Engadin', 'Playing at altitude', 'When to go']::text[], array['PDF guide', 'Venue map links']::text[], null, 'PDF', 19, 'USD', null, 'alpine', '27790371-0556-5829-a6b7-e16e5b7844e9', null, 'Coming soon.', true, false, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z'),
  ('2f0388db-9da7-5ea0-a3d9-1bb759b76aff', 'Japan Tennis Escape Guide', 'japan-tennis-escape-guide', 'From Karuizawa''s forests to Okinawa''s coast.', 'Our forthcoming guide to tennis travel in Japan.', array['Karuizawa', 'Okinawa', 'Etiquette and booking']::text[], array['PDF guide', 'Venue map links']::text[], null, 'PDF', 19, 'USD', null, 'zen', '72d3689a-b2ba-5eb2-b54f-9e4a28ad54f1', null, 'Coming soon.', true, false, '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z')
